text.congestNear:
function congestNear(x,y,r){
  let n=0;
  for(let dy=-r;dy<=r;dy++){const ny=y+dy;if(ny<0||ny>=N)continue;
    for(let dx=-r;dx<=r;dx++){const nx=x+dx;if(nx<0||nx>=N)continue;
      const j=idx(nx,ny),tt=tiles[j];
      if(tt.road&&roadLoad[j]>roadCap475(tt))n++;
    }}
  return n;
}

text.recomputeLandDynamic:
function recomputeLandDynamic(){
  /* T315 快路徑：LAND=clamp(LANDBASE−壅堵扣分)。原本每格都跑 landCongestAt（congestNear r=2＝25 格鄰域），
     432² 全圖＝470 萬次讀取／每 tick。但「過載道路」通常極少甚至沒有（空車城恆 0），此時壅堵扣分處處為 0，
     LAND 就等於 LANDBASE（LANDBASE 已 clamp 0-255）＝一次 TypedArray memcpy 即完全正確。
     有過載時也只需重算「過載格半徑2鄰域」（congestNear 的定義域），其餘維持 memcpy 結果。逐位元等價、非近似。 */
  const jam=[];
  for(let i=0;i<N*N;i++){
    if(roadLoad[i]===0)continue;                       // 多數格恆 0，先廉價跳過
    const t=tiles[i];
    if(t.road&&roadLoad[i]>roadCap475(t))jam.push(i);
  }
  LAND.set(LANDBASE);                                  // 基線＝無壅堵情形（一次 memcpy）
  if(!jam.length)return;
  for(const ji of jam){                                // 只修正受壅堵影響的鄰域
    const jx=ji%N,jy=(ji/N)|0;
    for(let dy=-2;dy<=2;dy++){const y=jy+dy;if(y<0||y>=N)continue;
      for(let dx=-2;dx<=2;dx++){const x=jx+dx;if(x<0||x>=N)continue;
        const i=idx(x,y);
        const v=LANDBASE[i]-landCongestAt(x,y);
        LAND[i]=v>0?(v<255?v:255):0;
      }}
  }
}

text.computeCommuteLegacyT141:
function computeCommuteLegacyT141(){
  commutePenalty.fill(0);
  commuteUnreach.fill(0);
  commuteClusters.length=0;
  const dsrc=[];
  for(let i=0;i<N*N;i++){const b=tiles[i].bld;if(b&&!b.ref&&(b.k===2||b.k===3))dsrc.push(i);}
  if(!dsrc.length)return; // 無就業區：全部維持零（不變量）
  const dist=new Uint16Array(N*N).fill(9999);
  const prev=new Int32Array(N*N).fill(-1);
  const q=[];
  for(const si of dsrc){
    const sx0=si%N,sy0=(si/N)|0;
    for(const[dx,dy]of DIRV){
      const nx=sx0+dx,ny=sy0+dy;
      if(inMap(nx,ny)){const j=idx(nx,ny);if(T(j).road&&dist[j]>0){dist[j]=0;q.push(j);}}
    }
  }
  let head=0;
  while(head<q.length){
    const cur=q[head++],d=dist[cur],cx=cur%N,cy=(cur/N)|0;
    for(const[dx,dy]of DIRV){
      const nx=cx+dx,ny=cy+dy;
      if(!inMap(nx,ny))continue;
      const j=idx(nx,ny);
      if(T(j).road&&dist[j]>d+1){dist[j]=d+1;prev[j]=cur;q.push(j);}
    }
  }
  const blkPerRow=Math.ceil(N/COMMUTE_CELL);
  const blkSeen=new Uint8Array(blkPerRow*blkPerRow);
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){
    const i=idx(x,y),b=tiles[i].bld;
    if(!b||b.ref||![1,127,33,105].includes(b.k))continue;
    let bd=9999,broad=-1;
    for(const[dx,dy]of DIRV){
      const nx=x+dx,ny=y+dy;
      if(!inMap(nx,ny))continue;
      const j=idx(nx,ny);
      if(T(j).road&&dist[j]<bd){bd=dist[j];broad=j;}
    }
    if(broad<0||bd>=9999){commuteUnreach[i]=1;commutePenalty[i]=COMMUTE_PEN_UNREACH;}
    else if(bd>COMMUTE_FAR){commutePenalty[i]=Math.min(COMMUTE_PEN_MAX,(bd-COMMUTE_FAR)*COMMUTE_PEN_STEP);}
    const blk=((x/COMMUTE_CELL)|0)*blkPerRow+((y/COMMUTE_CELL)|0); // 叢集鍵：粗網格分塊，塊內首個住宅格為代表
    if(blkSeen[blk])continue;
    blkSeen[blk]=1;
    if(broad<0||bd>=9999)continue; // 代表格本身不可達，該叢集無路徑可貢獻 load（不進 commuteClusters）
    const path=[];
    let c=broad,steps=0;
    while(c!==-1&&steps<600){path.push(c);c=prev[c];steps++;}
    commuteClusters.push({path});
  }
  // T468：真正存在的多模式可達性降低長距離道路通勤懲罰；低可達性不白送幸福。
  for(let i=0;i<N*N;i++){
    const b=tiles[i].bld;if(!b||b.ref||![1,127,33,105].includes(b.k))continue;
    const a=ACCESS468[i]||0;if(a<=0)continue;
    const mul=clamp(1-a/220,.35,.88);
    if(commuteUnreach[i]&&a>=80){commuteUnreach[i]=0;commutePenalty[i]=Math.min(.12,COMMUTE_PEN_UNREACH*mul);}
    else commutePenalty[i]*=mul;
  }
}

text.tick:
if(day%COMMUTE_PERIOD===0)computeCommute();
for(const cl of commuteClusters)for(const j of cl.path){roadPass[j]+=COMMUTE_TRIP_W;commutePass[j]+=COMMUTE_TRIP_W;}
// T129：道路壅堵場——用當日累計 roadPass 做衰減式移動平均，套公式後歸零累加器供下一天統計
// （純陣列運算，不消耗 R()；空車城 roadPass 恆 0 時 load 恆 0，speed/happyParts 與改動前逐位元一致）
for(let i=0;i<N*N;i++){roadLoad[i]=roadLoad[i]*.85+roadPass[i]*.15;roadPass[i]=0;}
